from pathlib import Path

import pandas as pd
import numpy as np

from sklearn.metrics import (
    mean_absolute_error,
    mean_squared_error,
    r2_score
)


# Load predictions generated by the final XGBoost model
BASE_DIR = Path(__file__).resolve().parent.parent
PREDICTIONS_PATH = BASE_DIR / "results" / "xgboost_predictions.csv"

df = pd.read_csv(PREDICTIONS_PATH)

print("\n--- LOADED XGBOOST PREDICTIONS ---")
print("Number of test rows:", len(df))
print("Columns:", list(df.columns))


def calculate_metrics(actual, predicted):
    """Calculate MAE, RMSE and R-squared."""

    mae = mean_absolute_error(
        actual,
        predicted
    )

    rmse = np.sqrt(
        mean_squared_error(
            actual,
            predicted
        )
    )

    r2 = r2_score(
        actual,
        predicted
    )

    return mae, rmse, r2


# Overall performance on the complete test set
xgb_mae, xgb_rmse, xgb_r2 = calculate_metrics(
    df["actual_points"],
    df["predicted_points"]
)

print("\n--- XGBOOST TEST PERFORMANCE ---")
print(f"MAE:  {xgb_mae:.4f}")
print(f"RMSE: {xgb_rmse:.4f}")
print(f"R²:   {xgb_r2:.4f}")


# Simple constant baseline used only as a diagnostic comparison.
# This currently uses the test-set mean and is not used for final model selection.
mean_prediction = df["actual_points"].mean()

df["mean_baseline_prediction"] = mean_prediction

baseline_mae, baseline_rmse, baseline_r2 = calculate_metrics(
    df["actual_points"],
    df["mean_baseline_prediction"]
)

print("\n--- SIMPLE MEAN BASELINE ---")
print(
    f"Constant prediction: "
    f"{mean_prediction:.4f} points"
)

print(f"MAE:  {baseline_mae:.4f}")
print(f"RMSE: {baseline_rmse:.4f}")
print(f"R²:   {baseline_r2:.4f}")


# Check how much of the test set consists of zero-point targets
zero_df = df[
    df["actual_points"] == 0
].copy()

nonzero_df = df[
    df["actual_points"] > 0
].copy()

zero_percentage = (
    len(zero_df)
    / len(df)
    * 100
)

print("\n--- TARGET DISTRIBUTION ---")
print("Zero-point rows:", len(zero_df))
print("Non-zero-point rows:", len(nonzero_df))
print(
    "Percentage zero:",
    round(zero_percentage, 2),
    "%"
)


# Evaluate separately on players who scored positive points
if len(nonzero_df) > 0:

    nonzero_mae, nonzero_rmse, nonzero_r2 = calculate_metrics(
        nonzero_df["actual_points"],
        nonzero_df["predicted_points"]
    )

    print(
        "\n--- XGBOOST PERFORMANCE "
        "ON NON-ZERO TARGETS ---"
    )

    print("Number of rows:", len(nonzero_df))
    print(f"MAE:  {nonzero_mae:.4f}")
    print(f"RMSE: {nonzero_rmse:.4f}")
    print(f"R²:   {nonzero_r2:.4f}")


# Evaluate players who actually appeared in the gameweek
played_df = df[
    df["minutes"] > 0
].copy()

played_mae, played_rmse, played_r2 = calculate_metrics(
    played_df["actual_points"],
    played_df["predicted_points"]
)

print(
    "\n--- XGBOOST PERFORMANCE: "
    "PLAYERS WITH MINUTES > 0 ---"
)

print("Number of rows:", len(played_df))
print(f"MAE:  {played_mae:.4f}")
print(f"RMSE: {played_rmse:.4f}")
print(f"R²:   {played_r2:.4f}")


# Compare errors across different actual point ranges
df["point_group"] = pd.cut(
    df["actual_points"],
    bins=[
        -np.inf,
        0,
        2,
        6,
        np.inf
    ],
    labels=[
        "0 points",
        "1-2 points",
        "3-6 points",
        "7+ points"
    ]
)

print("\n--- PERFORMANCE BY POINT RANGE ---")

for group in df["point_group"].cat.categories:

    group_df = df[
        df["point_group"] == group
    ]

    if len(group_df) == 0:
        continue

    group_mae = mean_absolute_error(
        group_df["actual_points"],
        group_df["predicted_points"]
    )

    print(
        f"{group}: "
        f"Rows = {len(group_df)}, "
        f"MAE = {group_mae:.4f}"
    )


# Optional diagnostic comparison with the constant baseline
comparison = pd.DataFrame({
    "Model": [
        "Mean Baseline",
        "XGBoost"
    ],
    "MAE": [
        baseline_mae,
        xgb_mae
    ],
    "RMSE": [
        baseline_rmse,
        xgb_rmse
    ],
    "R2": [
        baseline_r2,
        xgb_r2
    ]
})

print("\n--- BASELINE VS XGBOOST ---")

print(
    comparison.to_string(
        index=False
    )
)